define(['core/log','core/notification','core/str'],function(Log,Notification,Str){var attachConfirm=function(selector,fallbackMessage){document.querySelectorAll(selector).forEach(function(form){form.addEventListener('submit',function(e){if(form.dataset.confirmed==='1'){return;}e.preventDefault();var button=form.querySelector('[data-confirm]');var msg=(button&&button.getAttribute('data-confirm'))||fallbackMessage;Str.get_strings([{key:'confirm',component:'moodle'},{key:'yes',component:'moodle'},{key:'cancel',component:'moodle'}]).then(function(strings){return Notification.confirm(strings[0],msg,strings[1],strings[2],function(){form.dataset.confirmed='1';form.submit();});}).catch(function(){return Notification.confirm('Confirm',msg,'Yes','Cancel',function(){form.dataset.confirmed='1';form.submit();});});});});};return{init:function(config){config=config||{};attachConfirm('.videotrack-reset-student-form',config.confirmreset||'Reset this student?');attachConfirm('.videotrack-recalculate-form',config.confirmrecalculate||'Recalculate progress?');Log.debug('mod_videotrack/report: initialised');}};});
